import {
  bucketize,
  CliParseError,
  formatCliError,
  formatCliHelp,
  formatPythonBucketMap,
  formatPythonIntTraceback,
  getProgramName,
  parseArguments,
  parsePythonInt,
  PythonIntParseError,
} from './lib/index.mjs';

const programName = getProgramName(process.argv[1]);

try {
  const parsed = parseArguments(process.argv.slice(2));

  if (parsed.helpRequested) {
    process.stdout.write(formatCliHelp(programName));
    process.exit(0);
  }

  const numbers = parsed.a.split(',').map((item) => parsePythonInt(item));
  const result = bucketize(numbers, (value) => value % 2n === 0n);
  process.stdout.write(`${formatPythonBucketMap(result)}\n`);
} catch (error) {
  if (error instanceof CliParseError) {
    process.stderr.write(formatCliError(programName, error.message));
    process.exit(2);
  }

  if (error instanceof PythonIntParseError) {
    process.stderr.write(formatPythonIntTraceback(error.message, process.pid));
    process.exit(1);
  }

  throw error;
}

