export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliParseError';
  }
}

export function getProgramName(argvEntry) {
  if (!argvEntry) {
    return 'test5.mjs';
  }

  const parts = argvEntry.split(/[\\/]/);
  return parts[parts.length - 1] || 'test5.mjs';
}

export function parseArguments(argv) {
  let aValue = null;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { helpRequested: true };
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || next === '--' || (next.startsWith('-') && next !== '-')) {
        throw new CliParseError('argument --a: expected one argument');
      }

      aValue = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    unknown.push(token);
  }

  if (aValue === null) {
    throw new CliParseError('the following arguments are required: --a');
  }

  if (unknown.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${unknown.join(' ')}`);
  }

  return { helpRequested: false, a: aValue };
}

