import { formatPythonStringLiteral } from './format.mjs';

export class PythonIntParseError extends Error {
  constructor(input) {
    super(`invalid literal for int() with base 10: ${formatPythonStringLiteral(input)}`);
    this.name = 'PythonIntParseError';
    this.input = input;
  }
}

export function parsePythonInt(input) {
  const stripped = input.trim();

  if (!/^[+-]?(?:\d(?:_?\d)*)$/.test(stripped)) {
    throw new PythonIntParseError(input);
  }

  const normalized = stripped.replace(/_/g, '');
  const bigintSource = normalized.startsWith('+') ? normalized.slice(1) : normalized;
  return BigInt(bigintSource);
}

